   37	/**
   38	 * Reduces only the AI account's own current state into a transport-safe input.
   39	 *
   40	 * Enemy intelligence enters through explicitly published reports elsewhere;
   41	 * keeping it out here prevents a future policy from accidentally gaining host
   42	 * model access it was never meant to have.
   43	 */
   44	class PlayerObservationService
   45	{
   46	    /**
   47	     * How long one espionage report stays fresh enough to raid from, before the
   48	     * target has to be re-scouted. A stale target dies on its own; the account
   49	     * does not raid blind.
   50	     */
   51	    private const INTEL_TTL_HOURS = 24;
   52	
   53	    /** RAID-008: a target scoring under this fraction of ours is not worth the fleet. */
   54	    private const VIABILITY_SCORE_DIVISOR = 5;
   55	
   56	    /** CL3: the storage horizon (48 h) a colony's opening must repay inside, from E3. */
   57	    private const COLONY_DEVELOPMENT_HOURS = 48.0;
   58	
   59	    /** V2: the reaction window a hostile inbound wakes the account inside, in seconds before impact. */
   60	    private const REACTION_WINDOW_MIN_SECONDS = 120;
   61	
   62	    private const REACTION_WINDOW_MAX_SECONDS = 180;
   63	
   64	    /** V2: the host's own bot detector floor; a save closer than this to impact reads as scripted. */
   65	    private const REACTION_FLOOR_SECONDS = 10;
   66	
   67	    public function __construct(
   68	        private PlayerServiceFactory $playerServiceFactory,
   69	        private PlanetServiceFactory $planetServiceFactory,
   70	        private ActivityIntelReader $activityIntelReader,
   71	        private SettingsService $settings,
   72	        private QueueableBuildingPlanner $queueableBuildingPlanner,
   73	        private QueueableUnitPlanner $queueableUnitPlanner,
   74	        private QueueableColonyPlanner $queueableColonyPlanner,
   75	        private QueueableFleetSavePlanner $queueableFleetSavePlanner,
   76	        private QueueableSpyPlanner $queueableSpyPlanner,
   77	        private QueueableMinePercentPlanner $queueableMinePercentPlanner,
   78	        private SaveFailurePolicy $saveFailurePolicy,
   79	        private AccountStateResolver $accountStateResolver,
   80	        private RandomSource $randomSource,
   81	    ) {
   82	    }
   83	
   84	    /**
   85	     * @return array{
   86	     *     player_id:int,
   87	     *     observed_at:int,
   88	     *     account_state:string,
   89	     *     recovery_factor:float,
   90	     *     planets:array<int, array{id:int, resources:array<string, float|int>}>,
   91	     *     available_actions:array<string, bool>,
   92	     *     target_reports:array<int, array<string, mixed>>,
   93	     *     fleetsave_eligible:bool,
   94	     *     fleetsave_skip_reason:string|null,
   95	     *     inbound_fleets:list<array{mission_id:int, mission_type:int, time_arrival:int, planet_id_to:int}>,
   96	     *     reaction_wake_at:int|null,
   97	     *     recall_eligible:bool
   98	     * }
   99	     */
  100	    public function ownedState(int $playerId): array
  101	    {
  102	        $state = $this->accountStateResolver->resolve($playerId);
  103	        $active = $state === AiAccountState::Active;
  104	        // One player for the whole perception: every reader below shares this
  105	        // instance instead of rebuilding it per call site (~12 rebuilds -> 1).
  106	        $player = $active ? $this->playerServiceFactory->make($playerId, true) : null;
  107	
  108	        return [
  109	            'player_id' => $playerId,
  110	            'observed_at' => (int) now()->timestamp,
  111	            'account_state' => $state->value,
  112	            // W9-2: the scorer has always read this signal; publish it so a live
  113	            // decision carries the account's real, decaying recovery pressure.
  114	            'recovery_factor' => $active ? $this->recoveryFactor($playerId) : 0.0,
  115	            'planets' => $player === null ? [] : $this->planets($player),
  116	            // A suspended account is not playing, and the host is the authority
  117	            // on that state: a banned or vacationing account is offered nothing
  118	            // rather than a capability it cannot act on, so its session records
  119	            // that it did nothing instead of recording a decision the host
  120	            // would refuse. An account with no planets, and one the host no
  121	            // longer has, are offered nothing for the same reason.
  122	            'available_actions' => $player === null ? [] : $this->availableActions($player),
  123	            // The host's fleet-slot ceiling decides which dispatches may be published: a
  124	            // colony, spy, raid, expedition or transfer the host would refuse for slot
  125	            // exhaustion is never offered (SP8). Reaching the object that raises the
  126	            // ceiling is a host obligation (R11), not a module-side object list.
  127	            'fleet_slots_free' => $player === null ? 0 : $this->freeFleetSlots($player),
  128	            // CL3: a colony is founded only when the account's own production can bring it
  129	            // online — a body the account cannot develop outranks nothing and sits at zero.
  130	            'colonize_eligible' => $player !== null && $this->canDevelopColony($player),
  131	            // Enemy intel arrives through the host's own espionage-report
  132	            // messages, never from this module reaching into target state.
  133	            'target_reports' => $player === null ? [] : $this->targetReports($playerId, $player),
  134	            // Inbound fleets are assembled from the host's active fleet missions the same way
  135	            // the fleet movement page does. IncomingFleetIntelService only redacts a row that
  136	            // already exists; it is not the source of the inbound picture.
  137	            ...$this->inboundThreat($playerId, $active, $player),
  138	            ...$this->recallState($playerId, $active, $player),
  139	        ];
  140	    }
