  142	    /**
  143	     * The host's own fleet-slot answer, reduced to the free count a dispatch would need.
  144	     */
  145	    private function freeFleetSlots(PlayerService $player): int
  146	    {
  147	        return max(0, $player->getFleetSlotsMax() - $player->getFleetSlotsInUse());
  148	    }
  149	
  150	    /**
  151	     * Whether the account's own production can fund a new colony's opening (CL3).
  152	     *
  153	     * A colony starts at zero, and developing it is paid from what the account already produces;
  154	     * the cheapest production object the host offers is the opening step, and the account is eligible
  155	     * once its production covers that cost inside the storage horizon (the same 48 h E3 uses). The
  156	     * host supplies every object and price, so a mod that changes either changes this gate with no
  157	     * module edit.
  158	     */
  159	    private function canDevelopColony(PlayerService $player): bool
  160	    {
  161	        $planets = $player->planets->all();
  162	
  163	        $perHour = 0.0;
  164	
  165	        foreach ($planets as $planet) {
  166	            $perHour += $planet->getMetalProductionPerHour()
  167	                + $planet->getCrystalProductionPerHour()
  168	                + $planet->getDeuteriumProductionPerHour();
  169	        }
  170	
  171	        $cheapest = PHP_FLOAT_MAX;
  172	
  173	        foreach (ObjectService::getGameObjectsWithProduction() as $object) {
  174	            $price = ObjectService::getObjectRawPrice($object->machine_name);
  175	            $cheapest = min($cheapest, $price->metal->get() + $price->crystal->get() + $price->deuterium->get());
  176	        }
  177	
  178	        return $perHour * self::COLONY_DEVELOPMENT_HOURS >= $cheapest;
  179	    }
  180	
  181	    /**
  182	     * W9-2: the recovery signal the scorer has always read but never received.
  183	     *
  184	     * The only persisted, decaying setback signal is affect intensity: a battle the account
  185	     * came off worse in appraises to Anger (NativeAffectEngine) and decays 0.25/day, so the
  186	     * still-raw anger is the "not yet recovered" reading. ponytail: anger is a proxy — a true
  187	     * losses-vs-rebuilt ratio belongs to the experience layer (WP-015), and the affect decay is
  188	     * the closest existing bounded signal.
  189	     */
  190	    private function recoveryFactor(int $playerId): float
  191	    {
  192	        return app(CurrentAiAffectIntensityAction::class)->handle(
  193	            $playerId,
  194	            AiAffectEmotion::Anger,
  195	            CarbonImmutable::instance(now()),
  196	        );
  197	    }
