  199	    /**
  200	     * The espionage reports this account has received and can still act on.
  201	     *
  202	     * The host delivers a report as a message row carrying `espionage_report_id`;
  203	     * that row is the account's own record, so reading it here publishes only
  204	     * what the account has been told. The actual target state stays with the
  205	     * report and the estimator — no target model reaches a policy from here.
  206	     *
  207	     * @return array<int, array{report_id:int, observed_at:int, expires_at:int, confidence:float, travel_cost:float, activity:bool|null, attack_permitted:bool, score_viable:bool}>
  208	     */
  209	    private function targetReports(int $playerId, PlayerService $player): array
  210	    {
  211	        $now = now();
  212	        $cutoff = $now->copy()->subHours(self::INTEL_TTL_HOURS);
