  222	        if ($messages->isEmpty()) {
  223	            return [];
  224	        }
  225	
  226	        $reports = EspionageReport::query()
  227	            ->whereIn('id', $messages->pluck('espionage_report_id')->all())
  228	            ->get()
  229	            ->keyBy('id');
  230	
  231	        $nowTimestamp = (int) $now->timestamp;
  232	
