  400	    /**
  401	     * Foreign fleets headed at this account, and whether the host says that means under attack.
  402	     *
  403	     * Assembled from the host's active fleet missions the same way the fleet movement page does.
  404	     * Which missions count as hostile is the host's `currentPlayerUnderAttack()` answer — this
  405	     * module does not keep a mission-type list. The inbound rows carry only what every account
  406	     * can see without espionage (id, type, ETA, destination); composition stays with the host's
  407	     * redactor on the movement page.
  408	     *
  409	     * @return array{
  410	     *     fleetsave_eligible:bool,
  411	     *     fleetsave_skip_reason:string|null,
  412	     *     inbound_fleets:list<array{mission_id:int, mission_type:int, time_arrival:int, planet_id_to:int}>,
  413	     *     reaction_wake_at:int|null
  414	     * }
  415	     */
  416	    private function inboundThreat(int $playerId, bool $active, ?PlayerService $player): array
  417	    {
  418	        if (!$active || $player === null) {
  419	            return [
  420	                'fleetsave_eligible' => false,
  421	                'fleetsave_skip_reason' => null,
  422	                'inbound_fleets' => [],
  423	                'reaction_wake_at' => null,
  424	            ];
  425	        }
  426	
  427	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
  428	
  429	        $inbound = [];
  430	        $threatening = false;
  431	        foreach ($fleetMissions->getActiveFleetMissionsForCurrentPlayer() as $mission) {
  432	            if ($mission->user_id === $playerId) {
  433	                continue;
  434	            }
  435	
  436	            $inbound[] = [
  437	                'mission_id' => (int) $mission->id,
  438	                'mission_type' => (int) $mission->mission_type,
  439	                'time_arrival' => (int) $mission->time_arrival,
  440	                'planet_id_to' => (int) $mission->planet_id_to,
  441	            ];
  442	
  443	            // A spy probe alone is not a reason to move: only a non-espionage
  444	            // inbound is a threat worth saving from (FS-012). The type is the
  445	            // host's own mission-type answer, never a module list.
  446	            $threatening = $threatening || $mission->mission_type !== EspionageMission::getTypeId();
  447	        }
  448	
  449	        // A fleetsave candidate is only offered when it is both needed and possible: the host
  450	        // says a hostile is inbound, and the account has a fleet and a second body to move it
  451	        // to. Offering it otherwise is how a trace claims an action the account cannot take.
  452	        $saveable = $fleetMissions->currentPlayerUnderAttack()
  453	            && $threatening
  454	            && $this->queueableFleetSavePlanner->plan($playerId, $player) !== null;
  455	        $seed = AiProfile::query()->where('player_id', $playerId)->value('random_seed');
  456	        $seed = $seed === null ? null : (int) $seed;
  457	
  458	        // V2: a reaction lands inside the 120–180 s window before impact, never instantly and
  459	        // never below the host's 10 s detector floor. An early notice withholds the save and
  460	        // publishes the reaction wake instead; a notice past the floor is a doomed save the
  461	        // account does not attempt.
  462	        $earliestArrival = $inbound === [] ? null : (int) min(array_column($inbound, 'time_arrival'));
  463	        $reactionWakeAt = null;
  464	
  465	        if ($saveable && $earliestArrival !== null) {
  466	            $secondsToImpact = $earliestArrival - (int) now()->timestamp;
  467	
  468	            if ($secondsToImpact > self::REACTION_WINDOW_MAX_SECONDS) {
  469	                $reactionWakeAt = $earliestArrival - $this->reactionLeadSeconds($seed);
  470	                $saveable = false;
  471	            } elseif ($secondsToImpact < self::REACTION_FLOOR_SECONDS) {
  472	                $saveable = false;
  473	            }
  474	        }
  475	
  476	        // A save that fails is decided against a specific inbound fleet, so the same threat gets
  477	        // the same judgement however many times the session re-reads it.
  478	        if ($saveable) {
  479	            $key = $inbound === [] ? 0 : (int) min(array_column($inbound, 'mission_id'));
  480	            $skipReason = $this->saveFailurePolicy->shouldSkip($seed, $key);
  481	
  482	            if ($skipReason !== null) {
  483	                return [
  484	                    'fleetsave_eligible' => false,
  485	                    'fleetsave_skip_reason' => $skipReason,
  486	                    'inbound_fleets' => $inbound,
  487	                    'reaction_wake_at' => null,
  488	                ];
  489	            }
  490	        }
  491	
  492	        return [
  493	            'fleetsave_eligible' => $saveable,
  494	            'fleetsave_skip_reason' => null,
  495	            'inbound_fleets' => $inbound,
  496	            'reaction_wake_at' => $reactionWakeAt,
  497	        ];
  498	    }
  499	
  500	    /**
  501	     * The seconds before impact the account wakes to react: a deterministic per-account draw
  502	     * inside the 120–180 s window, so the same inbound always gets the same reaction and the
  503	     * reaction never lands below the host's 10 s detector floor.
  504	     */
  505	    private function reactionLeadSeconds(?int $seed): int
  506	    {
  507	        $unit = $this->randomSource->unitInterval($seed ?? 0, 'reaction-wake');
  508	
  509	        return self::REACTION_WINDOW_MIN_SECONDS
  510	            + (int) round((self::REACTION_WINDOW_MAX_SECONDS - self::REACTION_WINDOW_MIN_SECONDS) * $unit);
  511	    }
  512	
  513	    /**
  514	     * The recall is the other half of a save: the parked deployment comes home
  515	     * once the hostile that sent it away is gone. A deployment between two own
  516	     * bodies only, and never while the host still reports an attack.
  517	     *
  518	     * @return array{recall_eligible:bool}
  519	     */
  520	    private function recallState(int $playerId, bool $active, ?PlayerService $player): array
  521	    {
  522	        if (!$active || $player === null) {
  523	            return ['recall_eligible' => false];
  524	        }
  525	
  526	        $deploymentInFlight = FleetMission::query()
  527	            ->where('user_id', $playerId)
  528	            ->where('mission_type', DeploymentMission::getTypeId())
  529	            ->where('canceled', 0)
  530	            ->where('processed', 0)
  531	            ->where('time_arrival', '>=', now()->timestamp)
  532	            ->whereColumn('planet_id_from', '!=', 'planet_id_to')
  533	            ->exists();
