 14	class UtilityScorer
 15	{
 16	    private const RESOURCE_NEED_WEIGHT = 30.0;
 17	
 18	    private const SAFETY_WEIGHT = 50.0;
 19	
 20	    private const TARGET_CONFIDENCE_WEIGHT = 30.0;
 21	
 22	    private const TRAVEL_COST_WEIGHT = 25.0;
 23	
 24	    private const RECOVERY_WEIGHT = 20.0;
 25	
 26	    private const ARCHETYPE_WEIGHT = 25.0;
 27	
 28	    public function __construct(
